CREATE TABLE IF NOT EXISTS documents (id INT PRIMARY KEY AUTO_INCREMENT, organizationId INT NOT NULL, meetingId INT, title VARCHAR(255) NOT NULL, description TEXT, fileKey VARCHAR(500) NOT NULL, fileUrl VARCHAR(500) NOT NULL, mimeType VARCHAR(100), fileSize INT, version INT DEFAULT 1, documentType ENUM('boardPack', 'resolution', 'minutes', 'policy', 'other') DEFAULT 'other', isConfidential BOOLEAN DEFAULT false, uploadedBy INT NOT NULL, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_org_document (organizationId), INDEX idx_meeting_document (meetingId));
CREATE TABLE IF NOT EXISTS documentPermissions (id INT PRIMARY KEY AUTO_INCREMENT, documentId INT NOT NULL, userId INT, permission ENUM('view', 'edit', 'download', 'share', 'delete') NOT NULL, grantedBy INT NOT NULL, grantedAt DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX idx_doc_permission (documentId));
CREATE TABLE IF NOT EXISTS votes (id INT PRIMARY KEY AUTO_INCREMENT, organizationId INT NOT NULL, meetingId INT, resolutionId INT, title VARCHAR(255) NOT NULL, description TEXT, votingMethod ENUM('unanimous', 'majority', 'weighted', 'plurality') DEFAULT 'majority', status ENUM('open', 'closed', 'cancelled') DEFAULT 'open', result ENUM('passed', 'failed', 'abstained', 'pending') DEFAULT 'pending', createdBy INT NOT NULL, createdAt DATETIME DEFAULT CURRENT_TIMESTAMP, closedAt DATETIME, updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_org_vote (organizationId), INDEX idx_meeting_vote (meetingId));

